-- Add outreach without removing existing questions or student answers.
begin;
insert into public.assignment_questions (assignment_id, question_key, display_order, prompt, answer_type, required)
select a.id, 'conservation_email', 20, 'Write and send your own email to contact@savetheliontamarin.org with a parent or coach helping you review it. Use the coach’s outline as a guide, but use your own words and add something you personally did or want to learn. Introduce yourself and the Rainforest Rangers, fourth graders at Theodore Judah Elementary School in Folsom, California. Explain our November 1 bake sale at Prospector Park (cookies, brownies, hot chocolate, fruit cups, bracelets and stickers), the $200 raised and donated, and the requested $200 employer match. The match is pending: do not say $400 has been donated. Ask what the organization needs most and how children can help or educate others. Explain how forest fragmentation affects tamarins and describe our proposed canopy bridge: recycled-plastic parts only if experts find them suitable, local manufacture and jobs, native trees to build lasting connections, and safe public QR codes for sightings with small participation rewards while keeping exact animal locations private. These are ideas for feedback, not proven solutions. Ask about material safety and strength, improvements, and someone in Brazil who could talk with us. Ask them to confirm receipt of the donation and, when it arrives, the employer match. Include https://msriram.github.io/golden-lion-tamarin/index.html and sign with your own first name and team. In this response, paste your subject and email, record the date sent and one question you most want answered. You may attach a screenshot with personal addresses hidden. A reply is not required to complete this homework.', 'long_text', true
from public.assignments a
where a.team_id = 'b7024f8b-0db5-4ae5-a51d-8a189f7a421f' and a.week_number = 11
on conflict (assignment_id, question_key) do update set
  prompt = excluded.prompt, display_order = excluded.display_order, required = excluded.required;
commit;
